def execute_developer_tool(
    tool_name: str,
    *,
    repository_id: str,
    arguments: dict[str, Any] | None = None,
) -> Any:
    """
    Execute one developer tool through the shared registry.

    This function is intentionally independent of MCP and LangGraph.
    """

    if tool_name not in DEVELOPER_TOOL_REGISTRY:
        raise ValueError(
            f"Unknown developer tool: {tool_name}"
        )

    arguments = arguments or {}

    tool = DEVELOPER_TOOL_REGISTRY[tool_name]

    return tool(
        repository_id=repository_id,
        **arguments,
    )

def _run_async(
    coroutine: Any,
) -> Any:
    """
    Run an async MCP operation from the synchronous
    LangGraph execution path.
    """

    try:
        asyncio.get_running_loop()
    except RuntimeError:
        return asyncio.run(coroutine)

    raise RuntimeError(
        "MCP execution cannot use the synchronous adapter while "
        "an event loop is already running."
    )

def evaluate_current_investigation(
    state: dict[str, Any],
) -> dict[str, Any]:
    """
    Evaluate whether the investigation should continue.
    """

    from app.agent.evaluator import (
        COMPLETE,
        evaluate_investigation,
    )

    evaluation = evaluate_investigation(
        intent=state.get(
            "intent",
            "general_search",
        ),
        evidence=state.get(
            "evidence",
            [],
        ),
        executed_tools=state.get(
            "executed_tools",
            [],
        ),
        current_step=state.get(
            "current_step",
            0,
        ),
        max_steps=state.get(
            "max_steps",
            0,
        ),
    )

    state["investigation_decision"] = (
        evaluation.decision
    )

    state["investigation_reason"] = (
        evaluation.reason
    )

    if evaluation.decision == COMPLETE:

        state["needs_more_investigation"] = False
        state["investigation_complete"] = True

    else:

        state["needs_more_investigation"] = True
        state["investigation_complete"] = False

    return state

def should_continue(
    state: InvestigationState,
) -> str:
    """
    Decide whether another investigation tool should run.
    """

    if state.get(
        "needs_more_investigation",
        False,
    ):
        return "execute_tool"

    return "next"

def create_plan(
    state: dict[str, Any],
) -> dict[str, Any]:
    """
    Create a deterministic investigation plan.
    """

    try:

        plan = build_investigation_plan(
            intent=state.get(
                "intent",
                "general_search",
            ),
            identifiers=state.get(
                "identifiers",
                [],
            ),
            keywords=state.get(
                "keywords",
                [],
            ),
        )

        state["investigation_plan"] = [
            step.tool_name
            for step in plan.steps
        ]

        state["plan_reasons"] = {
            step.tool_name: step.reason
            for step in plan.steps
        }

        state["max_steps"] = plan.max_steps

        state["current_step"] = 0

        state["needs_more_investigation"] = bool(
            plan.steps
        )

    except Exception as exc:

        error = (
            f"Investigation planning failed: {exc}"
        )

        state["errors"] = (
            state.get("errors", [])
            + [error]
        )

        state["investigation_plan"] = [
            "repository_search"
        ]

        state["plan_reasons"] = {
            "repository_search": (
                "Fallback repository search."
            )
        }

        state["max_steps"] = 1
        state["current_step"] = 0

        state["needs_more_investigation"] = True

    return state

