def build_mcp_arguments(
    tool: MCPToolDefinition,
    *,
    repository_id: str,
    query: str,
    identifiers: list[str],
    keywords: list[str],
) -> dict[str, Any]:
    """
    Build arguments for a dynamically discovered MCP tool.

    Only arguments supported by the discovered schema are added.
    """

    schema = tool.input_schema or {}

    properties = schema.get(
        "properties",
        {},
    )

    arguments: dict[str, Any] = {}

    identifier = (
        identifiers[0]
        if identifiers
        else query
    )

    if "repository_id" in properties:
        arguments["repository_id"] = repository_id

    if tool.name == "search_text":
        if "query" in properties:
            arguments["query"] = identifier

        if "max_results" in properties:
            arguments["max_results"] = 50

        if "case_sensitive" in properties:
            arguments["case_sensitive"] = False

    elif tool.name == "repository_structure":
        if "max_files" in properties:
            arguments["max_files"] = 1000

    elif tool.name == "list_files":
        if "path" in properties:
            arguments["path"] = "."

    elif tool.name == "read_file":
        raise ValueError(
            "read_file requires an explicit repository-relative path."
        )

    else:
        if "query" in properties:
            arguments["query"] = query

        if "symbol" in properties:
            arguments["symbol"] = identifier

        if "keywords" in properties:
            arguments["keywords"] = keywords

    return arguments

def from_mcp_tool(
    cls,
    tool: Any,
    *,
    server_name: str,
) -> "MCPToolDefinition":
    return cls(
        name=tool.name,
        description=tool.description or "",
        input_schema=dict(tool.inputSchema),
        server_name=server_name,
        title=getattr(tool, "title", None),
    )

class PatchValidator:
    """
    Validates generated code changes without
    modifying the repository.
    """

    def __init__(
        self,
        repository_root: Path,
    ) -> None:
        self.repository_root = (
            repository_root.resolve()
        )

    def validate(
        self,
        proposal: ChangeProposal,
    ) -> ValidationResult:
        issues: list[
            ValidationIssue
        ] = []

        checked_files: list[str] = []

        issues.extend(
            validate_proposal_paths(
                proposal,
                self.repository_root,
            )
        )

        issues.extend(
            validate_proposal_changes(
                proposal
            )
        )

        for change in proposal.changes:
            if not change.is_modified:
                continue

            checked_files.append(
                change.path
            )

            if change.path.lower().endswith(
                ".py"
            ):
                issues.extend(
                    self._validate_python_file(
                        change.path,
                        change.proposed_content,
                    )
                )

        discovered_tests = (
            discover_tests(
                self.repository_root
            )
        )

        if not discovered_tests:
            issues.append(
                ValidationIssue(
                    severity=(
                        ValidationSeverity.WARNING
                    ),
                    code="NO_TESTS_FOUND",
                    message=(
                        "No test files were "
                        "discovered."
                    ),
                )
            )

        valid = not any(
            issue.severity
            == ValidationSeverity.ERROR
            for issue in issues
        )

        return ValidationResult(
            valid=valid,
            issues=issues,
            checked_files=checked_files,
            discovered_tests=(
                discovered_tests
            ),
        )

    def _validate_python_file(
        self,
        path: str,
        content: str,
    ) -> list[ValidationIssue]:
        issues: list[
            ValidationIssue
        ] = []

        syntax_issues = (
            validate_python_syntax(
                content,
                path=path,
            )
        )

        for (
            code,
            message,
            line,
        ) in syntax_issues:
            issues.append(
                ValidationIssue(
                    severity=(
                        ValidationSeverity.ERROR
                    ),
                    code=code,
                    message=message,
                    path=path,
                    line=line,
                )
            )

        # AST validation is only meaningful
        # if syntax parsing succeeded.
        if not syntax_issues:
            ast_issues = (
                validate_python_ast(
                    content,
                    path=path,
                )
            )

            for (
                code,
                message,
                line,
            ) in ast_issues:
                issues.append(
                    ValidationIssue(
                        severity=(
                            ValidationSeverity.ERROR
                        ),
                        code=code,
                        message=message,
                        path=path,
                        line=line,
                    )
                )

        return issues

    def validate_patch(
    self,
    proposal: ChangeProposal,
):
        """
        Run the complete Phase 4.3 validation pipeline.
        """

        validator = PatchValidator(
            self.repository_root
        )

        result = validator.validate(
            proposal
        )

        proposal.validation_errors.clear()
        proposal.validation_warnings.clear()

        for issue in result.issues:
            if (
                issue.severity.value
                == "error"
            ):
                proposal.validation_errors.append(
                    issue.message
                )

            elif (
                issue.severity.value
                == "warning"
            ):
                proposal.validation_warnings.append(
                    issue.message
                )

        if result.valid:
            proposal.status = (
                ChangeStatus.VALIDATED
            )
        else:
            proposal.status = (
                ChangeStatus.FAILED
            )

        return result

def prepare(
    self,
    proposal: ChangeProposal,
) -> ApprovalRequest:
    """
    Validate a proposal and prepare the
    information required for human review.

    No repository files are modified.
    """

    validation = (
        self.change_manager.validate_patch(
            proposal
        )
    )

    if not validation.valid:
        raise ApprovalError(
            "Patch failed validation and "
            "cannot be submitted for approval."
        )

    diff = self.change_manager.diff(
        proposal
    )

    return build_approval_request(
        proposal,
        diff=diff,
        validation=validation,
    )

class SafePatchApplier:
    """
    Applies only human-approved change proposals.

    Safety guarantees:

    - proposal must be APPROVED
    - paths must remain inside repository
    - protected files cannot be modified
    - backups are created before modification
    - writes are atomic
    - failed application attempts are rolled back
    """

    def __init__(
        self,
        repository_root: Path,
        backup_manager: BackupManager | None = None,
    ) -> None:
        self.repository_root = (
            repository_root.resolve()
        )

        self.backup_manager = (
            backup_manager
            if backup_manager is not None
            else BackupManager(
                self.repository_root
            )
        )

    def _validate_proposal(
        self,
        proposal: ChangeProposal,
    ) -> list[Path]:
        if proposal.status != (
            ChangeStatus.APPROVED
        ):
            raise PatchApplicationError(
                "Only APPROVED proposals can be applied."
            )

        if proposal.is_empty:
            raise PatchApplicationError(
                "Cannot apply an empty proposal."
            )

        validated_paths: list[Path] = []

        for change in proposal.changes:
            try:
                path = validate_change_path(
                    self.repository_root,
                    change.path,
                )
            except ChangeSafetyError as exc:
                raise PatchApplicationError(
                    str(exc)
                ) from exc

            validated_paths.append(path)

        return validated_paths

    def apply(
        self,
        proposal: ChangeProposal,
    ) -> ChangeProposal:
        """
        Apply an approved proposal safely.

        Any failure during application triggers
        restoration from the pre-change backup.
        """

        self._validate_proposal(
            proposal
        )

        changed_files = [
            change.path
            for change in proposal.changes
            if change.is_modified
        ]

        if not changed_files:
            raise PatchApplicationError(
                "Proposal contains no actual file changes."
            )

        backup_directory = (
            self.backup_manager.create_backup(
                proposal_id=proposal.proposal_id,
                paths=changed_files,
            )
        )

        applied_files: list[str] = []

        try:
            for change in proposal.changes:
                if not change.is_modified:
                    continue

                target = validate_change_path(
                    self.repository_root,
                    change.path,
                )

                atomic_write(
                    target,
                    change.proposed_content,
                )

                applied_files.append(
                    change.path
                )

            applied_at = datetime.now(
                timezone.utc
            ).isoformat()

            proposal.applied_files = (
                applied_files
            )

            proposal.backup_directory = (
                str(backup_directory)
            )

            proposal.applied_at = (
                applied_at
            )

            proposal.manifest = (
                ChangeManifest(
                    proposal_id=(
                        proposal.proposal_id
                    ),
                    repository_id=(
                        proposal.repository_id
                    ),
                    changed_files=(
                        list(applied_files)
                    ),
                    backup_directory=(
                        str(backup_directory)
                    ),
                    applied_at=(
                        applied_at
                    ),
                    rollback_available=True,
                )
            )

            proposal.status = (
                ChangeStatus.APPLIED
            )

            return proposal

        except Exception as exc:
            proposal.status = (
                ChangeStatus.FAILED
            )

            try:
                self.backup_manager.restore_backup(
                    backup_directory=(
                        backup_directory
                    ),
                    paths=changed_files,
                )

                proposal.status = (
                    ChangeStatus.ROLLED_BACK
                )

            except Exception as rollback_exc:
                raise PatchApplicationError(
                    "Patch application failed and "
                    "automatic rollback also failed."
                ) from rollback_exc

            raise PatchApplicationError(
                "Patch application failed. "
                "Repository was restored from backup."
            ) from exc

    def rollback(
        self,
        proposal: ChangeProposal,
    ) -> ChangeProposal:
        """
        Explicitly restore an applied proposal.
        """

        if proposal.status != (
            ChangeStatus.APPLIED
        ):
            raise PatchApplicationError(
                "Only APPLIED proposals can be rolled back."
            )

        if not proposal.backup_directory:
            raise PatchApplicationError(
                "No backup is available for rollback."
            )

        backup_directory = Path(
            proposal.backup_directory
        )

        self.backup_manager.restore_backup(
            backup_directory=backup_directory,
            paths=proposal.applied_files,
        )

        proposal.status = (
            ChangeStatus.ROLLED_BACK
        )

        if proposal.manifest is not None:
            proposal.manifest = (
                ChangeManifest(
                    proposal_id=(
                        proposal.manifest.proposal_id
                    ),
                    repository_id=(
                        proposal.manifest.repository_id
                    ),
                    changed_files=(
                        proposal.manifest.changed_files
                    ),
                    backup_directory=(
                        proposal.manifest.backup_directory
                    ),
                    applied_at=(
                        proposal.manifest.applied_at
                    ),
                    rollback_available=False,
                )
            )

        return proposal

