                "Only APPLIED proposals can be rolled back."
            )

        if not proposal.backup_directory:
            raise PatchApplicationError(
                "No backup is available for rollback."
            )

        backup_directory = Path(
            proposal.backup_directory
        )

        self.backup_manager.restore_backup(
            backup_directory=backup_directory,
            paths=proposal.applied_files,
        )

        proposal.status = (
            ChangeStatus.ROLLED_BACK
        )

        if proposal.manifest is not None:
            proposal.manifest = (
                ChangeManifest(
                    proposal_id=(
                        proposal.manifest.proposal_id
                    ),
                    repository_id=(
                        proposal.manifest.repository_id
                    ),
                    changed_files=(
                        proposal.manifest.changed_files
                    ),
                    backup_directory=(
                        proposal.manifest.backup_directory
                    ),
                    applied_at=(
                        proposal.manifest.applied_at
                    ),
                    rollback_available=False,
                )
            )

        return proposal

class ApplyAndVerify:
    """
    Coordinates:

        approved proposal
            ↓
        safe application
            ↓
        automated verification
            ↓
        rollback on failure
    """

    def __init__(
        self,
        repository_root: Path,
        test_timeout_seconds: float = 300.0,
    ) -> None:
        self.repository_root = (
            repository_root.resolve()
        )

        self.applier = SafePatchApplier(
            self.repository_root
        )

        self.verifier = ChangeVerifier(
            self.repository_root,
            timeout_seconds=(
                test_timeout_seconds
            ),
        )

    def execute(
        self,
        proposal: ChangeProposal,
    ) -> VerificationResult:
        """
        Apply and verify an approved proposal.

        If verification fails, automatically roll
        the repository back to its pre-change state.
        """

        try:
            self.applier.apply(
                proposal
            )

        except PatchApplicationError:
            raise

        verification = (
            self.verifier.verify(
                proposal
            )
        )

        if verification.passed:
            return verification

        rollback_error: str | None = None

        try:
            self.applier.rollback(
                proposal
            )

            verification.rollback_performed = (
                True
            )

        except Exception as exc:
            rollback_error = str(exc)

            verification.rollback_error = (
                rollback_error
            )

            raise PostChangeVerificationError(
                "Post-change verification failed "
                "and repository rollback failed."
            ) from exc

        return verification

def apply(
    self,
    proposal: ChangeProposal,
) -> ChangeProposal:
    """
    Apply an approved proposal safely.

    Any failure during application triggers
    restoration from the pre-change backup.
    """

    self._validate_proposal(
        proposal
    )

    changed_files = [
        change.path
        for change in proposal.changes
        if change.is_modified
    ]

    if not changed_files:
        raise PatchApplicationError(
            "Proposal contains no actual file changes."
        )

    backup_directory = (
        self.backup_manager.create_backup(
            proposal_id=proposal.proposal_id,
            paths=changed_files,
        )
    )

    applied_files: list[str] = []

    try:
        for change in proposal.changes:
            if not change.is_modified:
                continue

            target = validate_change_path(
                self.repository_root,
                change.path,
            )

            atomic_write(
                target,
                change.proposed_content,
            )

            applied_files.append(
                change.path
            )

        applied_at = datetime.now(
            timezone.utc
        ).isoformat()

        proposal.applied_files = (
            applied_files
        )

        proposal.backup_directory = (
            str(backup_directory)
        )

        proposal.applied_at = (
            applied_at
        )

        proposal.manifest = (
            ChangeManifest(
                proposal_id=(
                    proposal.proposal_id
                ),
                repository_id=(
                    proposal.repository_id
                ),
                changed_files=(
                    list(applied_files)
                ),
                backup_directory=(
                    str(backup_directory)
                ),
                applied_at=(
                    applied_at
                ),
                rollback_available=True,
            )
        )

        proposal.status = (
            ChangeStatus.APPLIED
        )

        return proposal

    except Exception as exc:
        proposal.status = (
            ChangeStatus.FAILED
        )

        try:
            self.backup_manager.restore_backup(
                backup_directory=(
                    backup_directory
                ),
                paths=changed_files,
            )

            proposal.status = (
                ChangeStatus.ROLLED_BACK
            )

        except Exception as rollback_exc:
            raise PatchApplicationError(
                "Patch application failed and "
                "automatic rollback also failed."
            ) from rollback_exc

        raise PatchApplicationError(
            "Patch application failed. "
            "Repository was restored from backup."
        ) from exc

    def apply(
    self,
    proposal: ChangeProposal,
) -> ChangeProposal:
        """
        Apply an approved proposal safely.
        """

        applier = SafePatchApplier(
            self.repository_root
        )

        return applier.apply(
            proposal
        )

def rollback(
    self,
    proposal: ChangeProposal,
) -> ChangeProposal:
    """
    Roll back an applied proposal.
    """

    applier = SafePatchApplier(
        self.repository_root
    )

    return applier.rollback(
        proposal
    )

def __init__(
    self,
    repository_root: Path,
    test_timeout_seconds: float = 300.0,
) -> None:
    self.repository_root = (
        repository_root.resolve()
    )

    self.applier = SafePatchApplier(
        self.repository_root
    )

    self.verifier = ChangeVerifier(
