class MCPAgentTools:
    """
    Adapter between the LangGraph agent and MCP tools.
    """

    def __init__(
        self,
        registry: MCPToolRegistry | None = None,
    ) -> None:
        self.registry = (
            registry
            if registry is not None
            else MCPToolRegistry(
                local_copilot_server_config()
            )
        )

    async def discover_tools(
        self,
    ) -> list[MCPToolDefinition]:
        """
        Discover MCP tools available to the agent.
        """

        return await self.registry.discover()

    def list_tools(
        self,
    ) -> list[MCPToolDefinition]:
        """
        Return currently discovered tools.
        """

        return self.registry.list_tools()

    async def execute(
        self,
        tool_name: str,
        arguments: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        """
        Execute an MCP tool and normalize its result.
        """

        result = await self.registry.execute(
            tool_name,
            arguments,
        )

        return normalize_mcp_result(
            result
        )

    def list_traces(
        self,
    ) -> list[MCPTrace]:
        """
        Return MCP execution traces.
        """

        return self.registry.client.tracer.list_traces()

    def trace_snapshot(
        self,
    ) -> list[dict[str, Any]]:
        """
        Return serializable MCP traces.
        """

        return self.registry.client.tracer.snapshot()

    def clear_traces(self) -> None:
        """
        Clear retained MCP traces.
        """

        self.registry.client.tracer.clear()

def index_mcp_tools(
    tools: list[MCPToolDefinition],
) -> dict[str, MCPToolDefinition]:
    """
    Build a runtime catalog from discovered MCP tools.
    """

    return {
        tool.name: tool
        for tool in tools
    }

def _symbol_match(
    candidate: dict,
    strategy: RetrievalStrategy,
) -> float:
    metadata = candidate["metadata"]

    symbol = str(metadata.get("symbol", "")).strip()
    symbol_type = str(metadata.get("symbol_type", "")).strip()

    if not strategy.prefer_symbols:
        return 0.0

    if not symbol:
        return -0.05

    if (
        strategy.preferred_symbol_types
        and symbol_type in strategy.preferred_symbol_types
    ):
        return 0.20

    return 0.10

def _normalize_result(result: Any) -> dict[str, Any]:
    """
    Convert a retrieval result into a stable evidence dictionary.

    This keeps the agent layer independent from the exact internal
    representation used by the retrieval layer.
    """

    if hasattr(result, "model_dump"):
        data = result.model_dump()
    elif hasattr(result, "__dict__"):
        data = dict(result.__dict__)
    elif isinstance(result, dict):
        data = dict(result)
    else:
        data = {"content": str(result)}

    return {
        "content": data.get("content", ""),
        "file": data.get("file", ""),
        "start_line": data.get("start_line"),
        "end_line": data.get("end_line"),
        "language": data.get("language"),
        "symbol": data.get("symbol"),
        "symbol_type": data.get("symbol_type"),
        "score": data.get("score"),
        "semantic_score": data.get("semantic_score"),
    }

def get_strategy(intent: str) -> RetrievalStrategy:
    return STRATEGIES.get(
        intent,
        STRATEGIES["general_search"],
    )

def _documentation_match(
    candidate: dict,
    strategy: RetrievalStrategy,
) -> float:
    if not strategy.prefer_documentation:
        return 0.0

    file_path = _normalise(
        str(candidate["metadata"].get("file", ""))
    )

    extension = str(
        candidate["metadata"].get("extension", "")
    ).lower()

    if extension in {".md", ".txt"}:
        return 0.12

    if "/docs/" in file_path or file_path.startswith("docs/"):
        return 0.12

    return 0.0

def _dependency_match(
    candidate: dict,
    strategy: RetrievalStrategy,
) -> float:
    if not strategy.prefer_dependencies:
        return 0.0

    file_path = _normalise(
        str(candidate["metadata"].get("file", ""))
    )

    if any(pattern in file_path for pattern in DEPENDENCY_PATTERNS):
        return 0.35

    return 0.0

def _entrypoint_match(
    candidate: dict,
    strategy: RetrievalStrategy,
) -> float:
    if not strategy.prefer_entrypoints:
        return 0.0

    file_path = Path(
        str(candidate["metadata"].get("file", ""))
    )

    stem = file_path.stem.lower()

    if stem in ENTRYPOINT_NAMES:
        return 0.30

    symbol = str(
        candidate["metadata"].get("symbol", "")
    ).lower()

    if symbol in ENTRYPOINT_NAMES:
        return 0.20

    return 0.0

