class RepositorySearch:
    """
    Deterministic text search inside a repository.
    """

    def __init__(self, filesystem: RepositoryFileSystem):
        self.filesystem = filesystem

    def search(
        self,
        query: str,
        max_results: int = 50,
        case_sensitive: bool = False,
    ) -> SearchResult:
        if not query.strip():
            raise ValueError("Search query cannot be empty.")

        if max_results < 1:
            raise ValueError(
                "max_results must be greater than zero."
            )

        matches: list[SearchMatch] = []

        for path in self._iter_files():
            if len(matches) >= max_results:
                break

            try:
                content = path.read_text(
                    encoding="utf-8",
                    errors="replace",
                )
            except OSError:
                continue

            for line_number, line in enumerate(
                content.splitlines(),
                start=1,
            ):
                haystack = line if case_sensitive else line.lower()
                needle = query if case_sensitive else query.lower()

                if needle in haystack:
                    matches.append(
                        SearchMatch(
                            path=path.relative_to(
                                self.filesystem.root
                            ).as_posix(),
                            line=line_number,
                            content=line.strip(),
                        )
                    )

                    if len(matches) >= max_results:
                        break

        return SearchResult(
            query=query,
            matches=matches,
        )

    def _iter_files(self):
        for path in self.filesystem.root.rglob("*"):
            if not path.is_file():
                continue

            if self._is_ignored(path):
                continue

            try:
                if (
                    path.stat().st_size
                    > settings.max_file_size_mb * 1024 * 1024
                ):
                    continue
            except OSError:
                continue

            yield path

    def _is_ignored(self, path: Path) -> bool:
        relative_parts = path.relative_to(
            self.filesystem.root
        ).parts

        return any(
            part in DEFAULT_IGNORED_DIRECTORIES
            for part in relative_parts
        )

def search_repository(
    request: SearchRequest,
):
    try:
        result = retrieve(
            repository_id=request.repository_id,
            query=request.query,
            top_k=request.top_k,
            language=request.language,
            symbol_type=request.symbol_type,
        )

        response_results = []

        for item in result["results"]:
            metadata = item["metadata"]

            response_results.append(
                SearchResult(
                    content=item["content"],
                    file=metadata.get("file", ""),
                    start_line=int(
                        metadata.get("start_line", 0)
                    ),
                    end_line=int(
                        metadata.get("end_line", 0)
                    ),
                    distance=float(
                        item["distance"]
                    ),
                    language=metadata.get(
                        "language"
                    ),
                    symbol=metadata.get(
                        "symbol"
                    ) or None,
                    symbol_type=metadata.get(
                        "symbol_type"
                    ) or None,
                    score=item.get("score"),
                    semantic_score=item.get(
                        "semantic_score"
                    ),
                )
            )

        return SearchResponse(
            query=request.query,
            repository_id=request.repository_id,
            intent=result["intent"].name,
            intent_confidence=result[
                "intent"
            ].confidence,
            results=response_results,
        )

    except Exception as exc:
        raise HTTPException(
            status_code=500,
            detail=f"Search failed: {exc}",
        ) from exc

def find_symbol(
    repository_id: str,
    symbol: str,
    top_k: int = 5,
) -> list[dict[str, Any]]:
    """
    Find where a symbol is defined or implemented.
    """

    return search_repository(
        repository_id=repository_id,
        query=f"Where is {symbol} defined?",
        top_k=top_k,
    )

def search_text(
    repository_id: str,
    query: str,
    max_results: int = 50,
    case_sensitive: bool = False,
):
    filesystem = RepositoryFileSystem(repository_id)
    searcher = RepositorySearch(filesystem)

    return searcher.search(
        query=query,
        max_results=max_results,
        case_sensitive=case_sensitive,
    )
